def to_roman(n):
    """Convert an integer 1..3999 to a Roman numeral string."""
    if not isinstance(n, int) or isinstance(n, bool) or n < 1 or n > 3999:
        raise ValueError(f"Expected integer in range 1..3999, got {n!r}")

    values = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'),
    ]

    result = []
    for value, numeral in values:
        count, n = divmod(n, value)
        result.append(numeral * count)
    return ''.join(result)


_ROMAN_VALUES = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

# Which symbols can be used as subtractive prefixes.
_SUB_PAIRS = {
    ('I', 'V'), ('I', 'X'),
    ('X', 'L'), ('X', 'C'),
    ('C', 'D'), ('C', 'M'),
}


def from_roman(s):
    """Convert a well-formed standard Roman numeral to its integer value.

    Raises ValueError for anything that isn't a valid canonical Roman numeral.
    """
    if not isinstance(s, str) or len(s) == 0:
        raise ValueError(f"Invalid Roman numeral: {s!r}")

    # All characters must be known Roman symbols.
    for ch in s:
        if ch not in _ROMAN_VALUES:
            raise ValueError(f"Invalid Roman numeral: {s!r}")

    total = 0
    prev = 0

    for i, ch in enumerate(reversed(s)):
        val = _ROMAN_VALUES[ch]
        if val < prev:
            # Subtractive: we already added prev, so subtract it and add val instead.
            total -= 2 * prev + val  # was += prev, now need -prev+val => net change = -(2*prev)+val
            # Actually let's redo the logic more carefully below.
            pass
        prev = val

    # Cleaner approach: scan left-to-right.
    total = 0
    i = 0
    while i < len(s):
        cur_val = _ROMAN_VALUES[s[i]]
        if i + 1 < len(s):
            next_val = _ROMAN_VALUES[s[i + 1]]
            if cur_val < next_val:
                # Subtractive pair: validate it's allowed.
                if (s[i], s[i + 1]) not in _SUB_PAIRS:
                    raise ValueError(f"Invalid Roman numeral: {s!r}")
                total += next_val - cur_val
                i += 2
                continue
        total += cur_val
        i += 1

    # Validate canonical form by round-tripping through to_roman.
    if to_roman(total) != s:
        raise ValueError(f"Roman numeral is not in canonical form: {s!r}")

    return total
